export class CitySound{
 constructor(){this.enabled=false;this.lastBeat=0;this.lastHorn=0;this.lastTalk=0;this.note=0;this.voices=window.speechSynthesis?.getVoices()||[]}
 async toggle(){if(!this.ctx)this.ctx=new(window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();this.enabled=!this.enabled;if(!this.enabled)window.speechSynthesis?.cancel();return this.enabled}
 tone(freq,duration=.15,type='sine',volume=.025,pan=0){if(!this.enabled||!this.ctx)return;let o=this.ctx.createOscillator(),g=this.ctx.createGain(),p=this.ctx.createStereoPanner();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);p.pan.value=pan;o.connect(g).connect(p).connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration)}
 speak(text){if(!this.enabled||!window.speechSynthesis)return;window.speechSynthesis.cancel();let s=new SpeechSynthesisUtterance(text);s.lang='id-ID';s.rate=1.12;s.pitch=1.15;s.volume=.45;window.speechSynthesis.speak(s)}
 update(t,walking){if(!this.enabled)return;if(t-this.lastBeat>.32){this.lastBeat=t;let melody=[523,659,784,659,587,698,880,698,523,659,784,1046,880,784,659,587];this.tone(melody[this.note++%16],.23,'sine',.012);if(this.note%4===0)this.tone(130,.22,'triangle',.014)}if(t-this.lastHorn>3.4+Math.random()*2){this.lastHorn=t;let f=[196,220,247,294][Math.floor(Math.random()*4)],pan=Math.sin(t);this.tone(f,.24,'triangle',.022,pan);this.tone(f*1.25,.22,'triangle',.012,pan);setTimeout(()=>this.tone(f,.15,'triangle',.018,-pan),330)}if(t-this.lastTalk>9){this.lastTalk=t;for(let i=0;i<4;i++)setTimeout(()=>this.tone(180+Math.random()*330,.1,'triangle',.012,Math.sin(t+i)),i*140)}if(walking&&this.note%3===0)this.tone(75,.04,'triangle',.005)}
}
